<span class="line">perf record <span class="token parameter variable">-F</span> <span class="token number">99</span> <span class="token parameter variable">-p</span> <span class="token variable"><span class="token variable">$(</span>pidof server<span class="token variable">)</span></span> <span class="token parameter variable">-g</span> -- <span class="token function">sleep</span> <span class="token number">60</span></span>
